import android.content.Context;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.TextView;

import androidx.recyclerview.widget.RecyclerView;

import java.util.List;

public class MLRecyclerAdapter extends RecyclerView.Adapter<MLRecyclerAdapter.ViewHolder> {

    private List<MorseEntry> mData;
    private LayoutInflater mInflater;
    private ItemClickListener mClickListener;

    // data is passed into the constructor
    MLRecyclerAdapter(Context context, List<MorseEntry> data) {
        this.mInflater = LayoutInflater.from(context);
        this.mData = data;
    }

    // inflates the row layout from xml when needed
    @Override
    public ViewHolder onCreateViewHolder(ViewGroup parent, int viewType) {
        View view = mInflater.inflate(R.layout.activity_mi, parent, false);
        return new ViewHolder(view);
    }

    // binds the data to the TextView in each row
    @Override
    public void onBindViewHolder(ViewHolder holder, int position) {
        MorseEntry entry = mData.get(position);

        holder.letterTextView.setText(entry.letter);
        holder.morseTextView.setText(entry.morse);
    }

    // total number of rows
    @Override
    public int getItemCount() {
        return mData.size();
    }


    // stores and recycles views as they are scrolled off screen
    public class ViewHolder extends RecyclerView.ViewHolder {
        TextView letterTextView;
        TextView morseTextView;

        ViewHolder(View itemView) {
            super(itemView);
            letterTextView = itemView.findViewById(R.id.Letter);
            morseTextView = itemView.findViewById(R.id.Morse);
        }
    }

    // convenience method for getting data at click position
    MorseEntry getItem(int id) {
        return mData.get(id);
    }

    // allows clicks events to be caught
    void setClickListener(ItemClickListener itemClickListener) {
        this.mClickListener = itemClickListener;
    }

    // parent activity will implement this method to respond to click events
    public interface ItemClickListener {
        void onItemClick(View view, int position);
    }
}

